prereqs={21:'Play after ‘Marshall Plan’ or ‘Warsaw Pact.’',101:'Requires John Paul II Elected Pope.'}
fix={17:'De Gaulle Leads France',38:'Southeast Asia Scoring',43:'SALT Negotiations',95:'Latin American Debt Crisis'}
by={int(p[0]):p for line in rows.strip().splitlines() if (p:=line.split('|'))}
base='Use case: historical-scene. Asset type: one landscape illustration for a premium Twilight Struggle game card. Subject: {subject}. Style: restrained photorealistic editorial illustration, convincingly real materials, recognizable at thumbnail size, a single clear focal subject, subtle film grain, natural cinematic light, muted Cold War palette of navy, warm ivory, brass and restrained red. Composition: landscape 3:2, close or medium view, subject contained in central 75 percent, enough quiet space in top corners for a badge and tiny UI text added later. This is the illustration only: no card frame, no UI, no labels, no headlines, no watermark, no collage, no decorative corners. Avoid crowds and human portraits. Historically grounded symbolic reconstruction, not a claim to archival photography.'
for c in raw:
    p=by[c['id']];c['title']=fix.get(c['id'],c['title']);c['titleZh']=p[1];c['effects']=p[2].split(' / ');c['prerequisite']=prereqs.get(c['id'],'')
    c['note']='MUST BE PLAYED THIS TURN.' if c['side']=='scoring' else ('REMOVE FROM PLAY IF USED AS AN EVENT.' if c['once'] else '')
    if c['id']==38:c['note']='MUST BE PLAYED THIS TURN. REMOVE AFTER SCORING.'
    if c['id']==6:c['note']='SPECIAL CARD · STARTS WITH THE USSR.'
    visual=json.loads((root/'tools/card-review/art-direction-v2.json').read_text())[str(c['id'])]
    c['art']=f"assets/v2/{c['id']:03}.webp";c['artPrompt']=visual['prompt'];c['artCategory']=visual['category'];c['revision']=2
    c['source']=json.loads((root/'tools/card-review/secondary-links.json').read_text()).get(str(c['id']),'https://twilightstrategy.com/card-list/')
    c['rulesSource']='https://s3-us-west-2.amazonaws.com/gmtwebsiteassets/vassal/Twilight-Struggle-Deluxe-3.04a.vmod.zip'
assert len(raw)==110 and len(by)==110
out=root/'prototypes/card-designs/final/cards.json';temp=out.with_suffix('.json.tmp');temp.write_text(json.dumps(raw,ensure_ascii=False,indent=2)+'\n');temp.replace(out)
print(f'Wrote {len(raw)} cards to {out}')
